import sys
import json
import re
import hashlib


ANONYMOUS = "sip:anonymous@anonymous.invalid"
ID_RE = re.compile(r"[A-Za-z][A-Za-z0-9_-]{0,31}\Z", re.ASCII)
TOKEN_RE = re.compile(r"[A-Za-z0-9\-.!%*_+`'~]+\Z", re.ASCII)
TAG_RE = re.compile(r"[ \t]*tag[ \t]*=[ \t]*([A-Za-z0-9\-.!%*_+`'~]{1,32})[ \t]*\Z", re.ASCII | re.IGNORECASE)
DISPLAY_RE = re.compile(r"[A-Za-z0-9\-.!%*_+`'~]+(?:[ \t]+[A-Za-z0-9\-.!%*_+`'~]+)*\Z", re.ASCII)
CALL_ID_RE = re.compile(r"[A-Za-z0-9_.@-]{1,64}\Z", re.ASCII)
CSEQ_RE = re.compile(r"([0-9]{1,10})[ \t]+(INVITE|MESSAGE)\Z", re.ASCII)
DIGITS_RE = re.compile(r"[0-9]+\Z", re.ASCII)
HOST_LABEL_RE = re.compile(r"[A-Za-z0-9-]+\Z", re.ASCII)
HEX_RE = re.compile(r"[0-9A-Fa-f]*\Z", re.ASCII)
USER_CHARS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.!~*'()")
HEX_CHARS = frozenset("0123456789abcdefABCDEF")
COMPACT = {"f": "from", "t": "to", "i": "call-id", "l": "content-length"}
SINGLETONS = ("from", "to", "call-id", "content-length", "cseq")


class EnvelopeError(Exception):
    pass


class Reject(Exception):
    def __init__(self, reason):
        self.reason = reason


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise EnvelopeError("duplicate object key")
        result[key] = value
    return result


def bad_json_number(_):
    raise EnvelopeError("non-integer JSON number")


def exact_object(value, keys):
    if type(value) is not dict or set(value) != set(keys):
        raise EnvelopeError("object shape")


def integer(value, low, high):
    if type(value) is not int or value < low or value > high:
        raise EnvelopeError("integer range")


def parse_uri(value):
    """Return (canonical URI, 'sip' for SIP/SIPS or 'tel'), or None."""
    if type(value) is not str or not value:
        return None
    colon = value.find(":")
    if colon <= 0:
        return None
    scheme = value[:colon].lower()
    rest = value[colon + 1:]

    if scheme == "sip" or scheme == "sips":
        if rest.count("@") != 1:
            return None
        raw_user, host_port = rest.split("@")
        if not raw_user:
            return None
        decoded = []
        i = 0
        while i < len(raw_user):
            char = raw_user[i]
            if char in USER_CHARS:
                decoded.append(char)
                i += 1
            elif char == "%" and i + 2 < len(raw_user):
                pair = raw_user[i + 1:i + 3]
                if pair[0] not in HEX_CHARS or pair[1] not in HEX_CHARS:
                    return None
                char = chr(int(pair, 16))
                if char not in USER_CHARS:
                    return None
                decoded.append(char)
                i += 3
            else:
                return None
        user = "".join(decoded)
        if not 1 <= len(user) <= 64:
            return None

        if host_port.count(":") > 1:
            return None
        if ":" in host_port:
            host, raw_port = host_port.split(":")
            if not 1 <= len(raw_port) <= 5 or not DIGITS_RE.fullmatch(raw_port):
                return None
            port = int(raw_port)
            if not 1 <= port <= 65535:
                return None
            canonical_port = ":" + str(port)
        else:
            host = host_port
            canonical_port = ""
        if not host or len(host) > 253:
            return None
        labels = host.split(".")
        if len(labels) < 2:
            return None
        for label in labels:
            if not 1 <= len(label) <= 63 or not HOST_LABEL_RE.fullmatch(label):
                return None
            if not (label[0].isascii() and label[0].isalnum()):
                return None
            if not (label[-1].isascii() and label[-1].isalnum()):
                return None
        if not ("A" <= labels[-1][0] <= "Z" or "a" <= labels[-1][0] <= "z"):
            return None
        canonical = scheme + ":" + user + "@" + host.lower() + canonical_port
        return canonical, "sip"

    if scheme == "tel":
        if len(rest) < 2 or rest[0] != "+":
            return None
        digits = []
        for char in rest[1:]:
            if "0" <= char <= "9":
                digits.append(char)
            elif char not in "-.()":
                return None
        number = "".join(digits)
        if not 3 <= len(number) <= 15 or not "1" <= number[0] <= "9":
            return None
        return "tel:+" + number, "tel"
    return None


def validate_envelope(document):
    exact_object(document, ("version", "config", "events"))
    if type(document["version"]) is not int or document["version"] != 1:
        raise EnvelopeError("version")
    config = document["config"]
    exact_object(config, ("accounts", "peers", "ttl_ms", "capacity"))
    integer(config["ttl_ms"], 1, 1000000)
    integer(config["capacity"], 1, 10000)

    raw_accounts = config["accounts"]
    if type(raw_accounts) is not list or len(raw_accounts) > 256:
        raise EnvelopeError("accounts")
    accounts = {}
    registry = {}
    for account in raw_accounts:
        exact_object(account, ("id", "default", "aliases"))
        account_id = account["id"]
        if type(account_id) is not str or not ID_RE.fullmatch(account_id) or account_id in accounts:
            raise EnvelopeError("account id")
        aliases = account["aliases"]
        if type(aliases) is not list or not 1 <= len(aliases) <= 8:
            raise EnvelopeError("aliases")
        seen = set()
        for alias in aliases:
            parsed = parse_uri(alias)
            if parsed is None or parsed[0] != alias or alias == ANONYMOUS:
                raise EnvelopeError("noncanonical alias")
            if alias in seen or alias in registry:
                raise EnvelopeError("duplicate alias")
            seen.add(alias)
            registry[alias] = account_id
        default = account["default"]
        if type(default) is not str or default not in seen:
            raise EnvelopeError("default")
        accounts[account_id] = default

    raw_peers = config["peers"]
    if type(raw_peers) is not list or not 1 <= len(raw_peers) <= 256:
        raise EnvelopeError("peers")
    peers = {}
    for peer in raw_peers:
        exact_object(peer, ("id", "mode", "accounts"))
        peer_id = peer["id"]
        if type(peer_id) is not str or not ID_RE.fullmatch(peer_id) or peer_id in peers:
            raise EnvelopeError("peer id")
        mode = peer["mode"]
        if mode not in ("access", "relay"):
            raise EnvelopeError("peer mode")
        allowed_list = peer["accounts"]
        if type(allowed_list) is not list:
            raise EnvelopeError("peer accounts")
        if mode == "access":
            if allowed_list:
                raise EnvelopeError("access accounts")
        else:
            seen = set()
            for account_id in allowed_list:
                if type(account_id) is not str or account_id not in accounts or account_id in seen:
                    raise EnvelopeError("relay account")
                seen.add(account_id)
        peers[peer_id] = (mode, frozenset(allowed_list))

    events = document["events"]
    if type(events) is not list or len(events) > 10000:
        raise EnvelopeError("events")
    previous_time = 0
    wire_total = 0
    for event in events:
        exact_object(event, ("t", "peer", "auth", "egress", "wire_hex"))
        timestamp = event["t"]
        integer(timestamp, 0, 9007199254740991)
        if timestamp < previous_time:
            raise EnvelopeError("descending time")
        previous_time = timestamp
        peer_id = event["peer"]
        if type(peer_id) is not str or peer_id not in peers:
            raise EnvelopeError("event peer")
        auth = event["auth"]
        if auth is not None and (type(auth) is not str or auth not in accounts):
            raise EnvelopeError("event auth")
        if peers[peer_id][0] == "relay" and auth is not None:
            raise EnvelopeError("relay auth")
        if event["egress"] not in ("internal", "external"):
            raise EnvelopeError("egress")
        wire = event["wire_hex"]
        if type(wire) is not str or len(wire) > 131072:
            raise EnvelopeError("wire size")
        wire_total += len(wire) // 2
        if wire_total > 8388608:
            raise EnvelopeError("aggregate wire size")
    return accounts, registry, peers, config["ttl_ms"], config["capacity"], events


def split_structured(value, delimiter):
    """Split outside quoted strings and angle brackets; address parsing validates syntax."""
    pieces = []
    start = 0
    angle_depth = 0
    quoted = False
    i = 0
    while i < len(value):
        char = value[i]
        if quoted:
            if char == "\\":
                i += 2
                continue
            if char == '"':
                quoted = False
        else:
            if char == '"':
                quoted = True
            elif char == "<":
                angle_depth += 1
            elif char == ">" and angle_depth:
                angle_depth -= 1
            elif char == delimiter and angle_depth == 0:
                pieces.append(value[start:i])
                start = i + 1
        i += 1
    pieces.append(value[start:])
    return pieces


def parse_address(value):
    text = value.strip(" \t")
    if not text:
        return None

    if "<" not in text and ">" not in text:
        return parse_uri(text)

    if text[0] == '"':
        i = 1
        closed = False
        while i < len(text):
            char = text[i]
            if char == "\\":
                if i + 1 >= len(text):
                    return None
                following = text[i + 1]
                if following != "\t" and not 0x21 <= ord(following) <= 0x7e:
                    return None
                i += 2
                continue
            if char == '"':
                closed = True
                i += 1
                break
            if char != " " and char != "\t" and not 0x21 <= ord(char) <= 0x7e:
                return None
            i += 1
        if not closed:
            return None
        while i < len(text) and text[i] in " \t":
            i += 1
        if i >= len(text) or text[i] != "<":
            return None
        opening = i
    else:
        opening = text.find("<")
        if opening < 0:
            return None
        display = text[:opening].strip(" \t")
        if display and not DISPLAY_RE.fullmatch(display):
            return None

    closing = text.find(">", opening + 1)
    if closing < 0 or text[closing + 1:]:
        return None
    uri = text[opening + 1:closing]
    if not uri or "<" in uri or ">" in uri or " " in uri or "\t" in uri:
        return None
    return parse_uri(uri)


def parse_from(value):
    pieces = split_structured(value, ";")
    if len(pieces) != 2:
        raise Reject("fields")
    address = parse_address(pieces[0])
    match = TAG_RE.fullmatch(pieces[1])
    if address is None or match is None:
        raise Reject("fields")
    return address[0], match.group(1)


def parse_identity_rows(headers, name):
    rows = [value for header, value in headers if header == name]
    if not rows:
        return None
    addresses = []
    for row in rows:
        if not row.strip(" \t"):
            raise Reject("fields")
        pieces = split_structured(row, ",")
        for piece in pieces:
            if not piece.strip(" \t"):
                raise Reject("fields")
            address = parse_address(piece)
            if address is None:
                raise Reject("fields")
            addresses.append(address)
    if len(addresses) not in (1, 2):
        raise Reject("fields")
    if len(addresses) == 2:
        if addresses[0][0] == addresses[1][0] or addresses[0][1] == addresses[1][1]:
            raise Reject("fields")
        if addresses[0][1] == "tel":
            addresses.reverse()
    return [address[0] for address in addresses]


def parse_privacy(headers):
    rows = [value for header, value in headers if header == "privacy"]
    if not rows:
        return "absent"
    tokens = set()
    for row in rows:
        for item in row.split(";"):
            item = item.strip(" \t").lower()
            if item not in ("id", "none"):
                raise Reject("fields")
            tokens.add(item)
    if len(tokens) != 1:
        raise Reject("fields")
    return next(iter(tokens))


def parse_syntax(data):
    if len(data) > 65536:
        raise Reject("syntax")
    delimiter = data.find(b"\r\n\r\n")
    if delimiter < 0:
        raise Reject("syntax")
    header_block = data[:delimiter]
    body = data[delimiter + 4:]
    if len(header_block) > 32768:
        raise Reject("syntax")

    i = 0
    while i < len(header_block):
        byte = header_block[i]
        if byte == 13:
            if i + 1 >= len(header_block) or header_block[i + 1] != 10:
                raise Reject("syntax")
            i += 2
            continue
        if byte == 10:
            raise Reject("syntax")
        if byte != 9 and not 0x20 <= byte <= 0x7e:
            raise Reject("syntax")
        i += 1

    lines = header_block.split(b"\r\n")
    if len(lines) - 1 > 256 or any(len(line) > 8192 for line in lines):
        raise Reject("syntax")
    start_parts = lines[0].split(b" ")
    if len(start_parts) != 3 or start_parts[0] not in (b"INVITE", b"MESSAGE") or start_parts[2] != b"SIP/2.0":
        raise Reject("syntax")
    method = start_parts[0].decode("ascii")
    try:
        raw_target = start_parts[1].decode("ascii")
    except UnicodeDecodeError:
        raise Reject("syntax")
    target = parse_uri(raw_target)
    if target is None or target[1] != "sip":
        raise Reject("syntax")

    headers = []
    for raw_line in lines[1:]:
        line = raw_line.decode("ascii")
        if line[0] in " \t":
            if not headers:
                raise Reject("syntax")
            name, old_value = headers[-1]
            headers[-1] = (name, old_value.rstrip(" \t") + " " + line.lstrip(" \t"))
            continue
        colon = line.find(":")
        if colon < 0:
            raise Reject("syntax")
        name = line[:colon].rstrip(" \t")
        if not TOKEN_RE.fullmatch(name):
            raise Reject("syntax")
        name = name.lower()
        name = COMPACT.get(name, name)
        headers.append((name, line[colon + 1:]))
    headers = [(name, value.strip(" \t")) for name, value in headers]
    return method, target[0], headers, body


def required_fields(headers):
    fields = {}
    for name, value in headers:
        if name in SINGLETONS:
            if name in fields:
                raise Reject("headers")
            fields[name] = value
    for name in SINGLETONS:
        if name not in fields:
            raise Reject("headers")
    return fields


def check_length(fields, body):
    value = fields["content-length"]
    if not value or len(value) > 10 or not DIGITS_RE.fullmatch(value):
        raise Reject("length")
    if int(value) != len(body):
        raise Reject("length")


def parse_fields(method, target, headers, fields):
    from_uri, tag = parse_from(fields["from"])

    to_address = parse_address(fields["to"])
    if to_address is None or to_address[1] != "sip" or to_address[0] != target:
        raise Reject("fields")

    call_id = fields["call-id"]
    if not CALL_ID_RE.fullmatch(call_id):
        raise Reject("fields")

    match = CSEQ_RE.fullmatch(fields["cseq"])
    if match is None:
        raise Reject("fields")
    cseq = int(match.group(1))
    if not 1 <= cseq <= 2147483647 or match.group(2) != method:
        raise Reject("fields")

    pai = parse_identity_rows(headers, "p-asserted-identity")
    ppi = parse_identity_rows(headers, "p-preferred-identity")
    privacy = parse_privacy(headers)
    return from_uri, tag, call_id, cseq, pai, ppi, privacy


def process_event(event, accounts, registry, peers):
    wire = event["wire_hex"]
    if len(wire) % 2 or not HEX_RE.fullmatch(wire):
        raise Reject("hex")
    data = bytes.fromhex(wire)
    method, target, headers, body = parse_syntax(data)
    fields = required_fields(headers)
    check_length(fields, body)
    from_uri, tag, call_id, cseq, pai, ppi, privacy = parse_fields(method, target, headers, fields)

    peer_id = event["peer"]
    mode, allowed = peers[peer_id]
    if mode == "access":
        account = event["auth"]
        if account is None:
            raise Reject("auth")
        if ppi is None:
            selected = accounts[account]
            asserted = [selected]
        else:
            for uri in ppi:
                if registry.get(uri) != account:
                    raise Reject("identity")
            asserted = ppi
            selected = ppi[0]
    else:
        if ppi is not None or pai is None:
            raise Reject("identity")
        account = None
        for uri in pai:
            owner = registry.get(uri)
            if owner is None or (account is not None and owner != account):
                raise Reject("identity")
            account = owner
        if account not in allowed:
            raise Reject("identity")
        asserted = pai
        selected = pai[0]

    if from_uri == ANONYMOUS:
        if privacy != "id":
            raise Reject("identity")
    elif registry.get(from_uri) != account:
        raise Reject("identity")

    outgoing_from = ANONYMOUS if privacy == "id" else selected
    if event["egress"] == "external" and privacy in ("id", "absent"):
        outgoing_pai = []
    else:
        outgoing_pai = list(asserted)
    commitment = (account, selected, tuple(asserted), from_uri, tag, target,
                  privacy, event["egress"], body)
    key = (peer_id, call_id, cseq, method)
    result = {
        "account": account,
        "identity": selected,
        "from": outgoing_from,
        "pai": outgoing_pai,
        "method": method,
        "target": target,
        "call_id": call_id,
        "cseq": cseq,
        "tag": tag,
        "privacy": privacy,
        "body_sha256": hashlib.sha256(body).hexdigest(),
    }
    return key, commitment, result


def run(document):
    accounts, registry, peers, ttl, capacity, events = validate_envelope(document)
    ledger = {}
    results = []
    accepted = 0
    replayed = 0
    rejected = 0

    for index, event in enumerate(events):
        timestamp = event["t"]
        while ledger:
            oldest_key = next(iter(ledger))
            entry = ledger[oldest_key]
            if timestamp < entry[2] + ttl:
                break
            del ledger[oldest_key]
        try:
            key, commitment, normalized = process_event(event, accounts, registry, peers)
            old = ledger.get(key)
            if old is not None:
                if old[0] != commitment:
                    raise Reject("conflict")
                first = old[1]
                decision = "replay"
                replayed += 1
            else:
                if len(ledger) >= capacity:
                    del ledger[next(iter(ledger))]
                first = index
                ledger[key] = (commitment, first, timestamp)
                decision = "accept"
                accepted += 1
            result = {"index": index, "decision": decision, "first": first}
            result.update(normalized)
            results.append(result)
        except Reject as failure:
            results.append({"index": index, "decision": "reject", "reason": failure.reason})
            rejected += 1

    return {"results": results, "accepted": accepted, "replayed": replayed,
            "rejected": rejected, "live": len(ledger)}


def main():
    try:
        raw = sys.stdin.buffer.read()
        if len(raw) > 33554432 or raw.startswith(b"\xef\xbb\xbf"):
            raise EnvelopeError("input encoding or size")
        text = raw.decode("utf-8")
        document = json.loads(text, object_pairs_hook=unique_object,
                              parse_float=bad_json_number, parse_constant=bad_json_number)
        output = run(document)
    except (EnvelopeError, UnicodeError, ValueError, TypeError, RecursionError, json.JSONDecodeError):
        return 2
    sys.stdout.write(json.dumps(output, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
